def main():
    print(f"Translating {len(DOC_FILES)} markdown documentation files to French...")
    for rel_path in DOC_FILES:
        build_localized_file(rel_path, "fr", TRANSLATIONS_FR)

    # Verification
    docs_dir = os.path.join(REPO_ROOT, "docs")
    fr_dir = os.path.join(docs_dir, "fr")
    generated_files = []
    for root, dirs, files in os.walk(fr_dir):
        for file in files:
            if file.endswith(".md"):
                rel_path = os.path.relpath(os.path.join(root, file), fr_dir)
                generated_files.append(rel_path.replace("\\", "/"))

    generated_files.sort()
    print(f"Successfully generated {len(generated_files)} French documentation files in docs/fr/.")
    if len(generated_files) == len(DOC_FILES):
        print("Verification passed: All 59 documentation files generated successfully.")
    else:
        print(f"Verification mismatch: Expected {len(DOC_FILES)} files, but found {len(generated_files)}.")

if __name__ == "__main__":
    main()
